  private touchMove=(e:PointerEvent)=>{if(!this.touchLook||this.touchLook.id!==e.pointerId)return;const sensitivity=(this.world.life?.settings.sensitivity||1)*.006;this.player.yaw-=(e.clientX-this.touchLook.x)*sensitivity;this.player.pitch=T.MathUtils.clamp(this.player.pitch-(e.clientY-this.touchLook.y)*sensitivity*(this.world.life?.settings.invertY?-1:1),-1.4,1.4);this.touchLook.x=e.clientX;this.touchLook.y=e.clientY}
