    const point={x:hit.x,y:surfaceAt(hit.x,hit.z,this.world,hit.y+.2)+.08,z:hit.z}
    if(Math.hypot(point.x-this.player.x,point.z-this.player.z)>185||!clear(point,this.world)||!this.world.life?.interior&&point.y<=waterAt(point.x,point.z,this.world)+.1){this.callbacks.message('Choose dry, open ground for a walking destination.');return}
