  private mouseDown=(e:MouseEvent)=>{this.renderer.domElement.focus({preventScroll:true});if(this.world.life?.paused)return;this.mouseTravel.press(e.button,e.buttons);if(e.button===2||this.mouseTravel.forward)this.cancelClickTravel()}
