  setSettings(settings:ToolSettings){this.settings=settings;if(settings.tool!=='explore')this.releaseInput()}
  getPlayer(){return {...this.player}}
  getCombatDiagnostics(){return this.combat.diagnostics}
  getPerformanceDiagnostics(){const times=this.frameTimes.map(t=>t*1000).sort((a,b)=>a-b);return {frames:times.length,p50:times[Math.floor(times.length*.5)],p95:times[Math.floor(times.length*.95)],max:times.at(-1),terrain:{loaded:this.chunks.size,queued:this.queue.length,inflight:this.inflight.size},renderer:{...this.renderer.info.memory,drawCalls:this.renderer.info.render.calls,triangles:this.renderer.info.render.triangles},animalModels:[...this.animalModels],animalClips:[...this.objects].filter(([,o])=>o.userData.kind==='animal').map(([id,o])=>({id,clip:o.userData.clip,position:o.position.toArray()})),residentModels:this.residents.size}}
