    this.renderer.render(this.scene,this.camera);this.frameTimes.push(rawDt);if(this.frameTimes.length>120)this.frameTimes.shift();this.viewTimer+=dt;if(this.viewTimer>0.15){this.viewTimer=0;if(new URLSearchParams(location.search).has('combatQA'))this.renderer.domElement.dataset.combatQa=JSON.stringify({worldId:this.world.id,time:this.world.time,input:{mouseForward:this.mouseTravel.forward,clickDestination:this.clickDestination},player:{...this.player,vitality:combatActor(this.world,'player')?.vitality},actors:this.world.combat?.actors.filter(a=>Math.hypot(a.position.x-this.player.x,a.position.z-this.player.z)<200),view:this.combat.diagnostics,performance:this.getPerformanceDiagnostics(),drawCalls:this.renderer.info.render.calls});const label=this.updateTarget();this.callbacks.view({x:this.player.x,y:this.player.y,z:this.player.z,fps:Math.round(this.frameTimes.length/this.frameTimes.reduce((a,b)=>a+b,0)),pending:this.queue.length+this.inflight.size,target:label,targetId:this.targetId,targetKind:this.target,yaw:this.player.yaw,caption:this.skyTime<this.captionUntil?this.caption:undefined,region:this.world.life?.interior?.label||(isAtlas(this.world)?regionAt(this.player.x,this.player.z):this.cinderlord&&Math.hypot(this.player.x-this.cinderlord.site.x,this.player.z-this.cinderlord.site.z)<90?'Ashen Hollow':this.player.x>1050&&this.player.z>1050?'Fangorn Forest':'The Shire'),enemy:this.cinderlord&&Math.hypot(this.player.x-this.cinderlord.site.x,this.player.z-this.cinderlord.site.z)<60?this.cinderlord.status:undefined,locked:document.pointerLockElement===this.renderer.domElement,preview:this.previewLabel});this.loadResidents();this.cinderlord?.load(this.availableAssets.get(CINDERLORD.assetId),this.player)}
